fn json_escape(s: &str) -> String {
    let mut out = String::from("");
    let mut i = 0i64;
    while (i < s.revl_length()) {
        let c = { s.chars().nth((i) as usize).unwrap().to_string() };
        let cc = { c.chars().nth((0i64) as usize).unwrap() as u32 as i64 };
        if (c == "\\") {
            out.push_str("\\\\");
        } else {
            if (c == "\"") {
                out.push_str("\\\"");
            } else {
                if (cc == 10i64) {
                    out.push_str("\\n");
                } else {
                    if (cc == 9i64) {
                        out.push_str("\\t");
                    } else {
                        if (cc == 13i64) {
                            out.push_str("\\r");
                        } else {
                            out.push_str(&c);
                        }
                    }
                }
            }
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return out;
}

fn jstr(s: &str) -> String {
    return (String::from("\"").revl_concat(&json_escape(s))).revl_concat("\"");
}

fn ty_ident_char(c: &str) -> bool {
    return ({ let _rc: &str = &c; ("0" <= _rc && _rc <= "9") || ("a" <= _rc && _rc <= "z") || ("A" <= _rc && _rc <= "Z") } || (c == "_"));
}

fn ty_split_args(s: &str) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut depth = 0i64;
    let mut start = 0i64;
    let mut i = 0i64;
    while (i < s.revl_length()) {
        let c = { s.chars().nth((i) as usize).unwrap().to_string() };
        if ((c == "[") || (c == "(")) {
            depth = (depth).checked_add(1i64).expect("revl: Int overflow");
        } else {
            if ((c == "]") || (c == ")")) {
                depth = (depth).checked_sub(1i64).expect("revl: Int overflow");
            } else {
                if ((c == ",") && (depth == 0i64)) {
                    out.push(ty_trim(&(s.revl_slice(start, i))));
                    start = (i).checked_add(1i64).expect("revl: Int overflow");
                }
            }
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    let last = ty_trim(&(s.revl_slice(start, s.revl_length())));
    if (last != "") {
        out.push(last.clone());
    }
    return out;
}

fn ty_close_paren(ty: &str) -> i64 {
    let mut depth = 0i64;
    let mut i = 0i64;
    while (i < ty.revl_length()) {
        let c = { ty.chars().nth((i) as usize).unwrap().to_string() };
        if (c == "(") {
            depth = (depth).checked_add(1i64).expect("revl: Int overflow");
        } else {
            if (c == ")") {
                depth = (depth).checked_sub(1i64).expect("revl: Int overflow");
                if (depth == 0i64) {
                    return i;
                }
            }
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return (0i64).checked_sub(1i64).expect("revl: Int overflow");
}

fn ty_parse(ty: String) -> TyParts {
    if ty.revl_starts_with("(") {
        let close = ty_close_paren(&ty);
        if ((close != (0i64).checked_sub(1i64).expect("revl: Int overflow")) && (ty.revl_slice(close, ty.revl_length())).revl_starts_with(") -> ")) {
            let ps = ty_split_args(&(ty.revl_slice(1i64, close)));
            return TyParts { head: String::from("->"), args: ps.revl_push(ty.revl_slice((close).checked_add(5i64).expect("revl: Int overflow"), ty.revl_length())) };
        }
        return TyParts { head: ty.clone(), args: vec![] };
    }
    let br = ty.revl_index_of("[");
    if ((br == (0i64).checked_sub(1i64).expect("revl: Int overflow")) || (!ty.revl_ends_with("]"))) {
        return TyParts { head: ty.clone(), args: vec![] };
    }
    return TyParts { head: ty.revl_slice(0i64, br), args: ty_split_args(&(ty.revl_slice((br).checked_add(1i64).expect("revl: Int overflow"), (ty.revl_length()).checked_sub(1i64).expect("revl: Int overflow")))) };
}

fn ty_render(head: String, args: &[String]) -> String {
    if (args.revl_length() == 0i64) {
        return head;
    }
    if (head == "->") {
        let mut ps: Vec<String> = vec![];
        let mut i = 0i64;
        while (i < (args.revl_length()).checked_sub(1i64).expect("revl: Int overflow")) {
            ps.push((args)[(i) as usize].clone());
            i = (i).checked_add(1i64).expect("revl: Int overflow");
        }
        return ((String::from("(").revl_concat(&ps.revl_join(", "))).revl_concat(") -> ")).revl_concat(&(args)[((args.revl_length()).checked_sub(1i64).expect("revl: Int overflow")) as usize]);
    }
    return ((head.revl_concat("[")).revl_concat(&args.revl_join(", "))).revl_concat("]");
}

fn is_qual_head(h: &str) -> bool {
    return (((h == "Secret") || (h == "Trusted")) || (h == "Untrusted"));
}

fn taint_has_qualifier(ty: &str) -> bool {
    let mut i = 0i64;
    while (i < ty.revl_length()) {
        if ({ ty.chars().nth((i) as usize).unwrap().to_string() } == "[") {
            let mut a = i;
            while ((a > 0i64) && ty_ident_char(&({ ty.chars().nth(((a).checked_sub(1i64).expect("revl: Int overflow")) as usize).unwrap().to_string() }))) {
                a = (a).checked_sub(1i64).expect("revl: Int overflow");
            }
            if is_qual_head(&(ty.revl_slice(a, i))) {
                return true;
            }
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return false;
}

fn taint_strip(ty: String) -> String {
    if ((ty == "") || (!taint_has_qualifier(&ty))) {
        return ty;
    }
    let p = ty_parse(ty.clone());
    if (is_qual_head(&p.head) && (p.args.revl_length() == 1i64)) {
        return taint_strip((p.args)[(0i64) as usize].clone());
    }
    if (p.args.revl_length() == 0i64) {
        return p.head;
    }
    let mut out: Vec<String> = vec![];
    let mut i = 0i64;
    while (i < p.args.revl_length()) {
        out.push(taint_strip((p.args)[(i) as usize].clone()));
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return ty_render(p.head.clone(), &out);
}

fn taint_mentions_secret(ty: String) -> bool {
    if (ty == "") {
        return false;
    }
    let p = ty_parse(ty.clone());
    if (p.head == "Secret") {
        return true;
    }
    if ((p.head == "->") || (p.head == "Fn")) {
        return false;
    }
    let mut i = 0i64;
    while (i < p.args.revl_length()) {
        if taint_mentions_secret((p.args)[(i) as usize].clone()) {
            return true;
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return false;
}

fn taint_secret_witness(ty: String) -> bool {
    if (ty == "") {
        return false;
    }
    let p = ty_parse(ty.clone());
    return (((p.head == "Result") && (p.args.revl_length() == 2i64)) && taint_mentions_secret((p.args)[(0i64) as usize].clone()));
}

fn taint_decl_at(ts: Vec<Token>, i: i64) -> TaintDecl {
    let mut j = (i).checked_add(1i64).expect("revl: Int overflow");
    if atw(&ts, i, "extern") {
        j = (j).checked_add(1i64).expect("revl: Int overflow");
        if atk(&ts, j.clone(), "[") {
            j = skip_brackets(&ts, j.clone());
        }
        if atw(&ts, j, "async") {
            j = (j).checked_add(1i64).expect("revl: Int overflow");
        }
        if (!atw(&ts, j, "fn")) {
            return TaintDecl { name: String::from(""), types: vec![] };
        }
        j = (j).checked_add(1i64).expect("revl: Int overflow");
    }
    let nm = tkc(&ts, j).text;
    j = (j).checked_add(1i64).expect("revl: Int overflow");
    if atk(&ts, j, "[") {
        j = skip_brackets(&ts, j);
    }
    if (!atk(&ts, j, "(")) {
        return TaintDecl { name: String::from(""), types: vec![] };
    }
    let ps = params_at(ts.clone(), (j).checked_add(1i64).expect("revl: Int overflow"));
    let mut types: Vec<String> = vec![];
    let mut k = 0i64;
    while (k < ps.ps.revl_length()) {
        types.push((ps.ps)[(k) as usize].ty.clone());
        k = (k).checked_add(1i64).expect("revl: Int overflow");
    }
    return TaintDecl { name: nm.clone(), types: types.clone() };
}

fn taint_decl_params(ts: Vec<Token>) -> Vec<TaintDecl> {
    let mut out: Vec<TaintDecl> = vec![];
    let mut d = 0i64;
    let mut i = 0i64;
    while (i < ts.revl_length()) {
        if atk(&ts, i, "{") {
            d = (d).checked_add(1i64).expect("revl: Int overflow");
        } else {
            if atk(&ts, i, "}") {
                d = (d).checked_sub(1i64).expect("revl: Int overflow");
            } else {
                if ((d == 0i64) && (atw(&ts, i, "extern") || atw(&ts, i, "fn"))) {
                    let dec = taint_decl_at(ts.clone(), i);
                    if (dec.name != "") {
                        out.push(dec.clone());
                    }
                }
            }
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return out;
}

fn taint_params_of(ds: &[TaintDecl], name: &str) -> Vec<String> {
    let mut i = 0i64;
    while (i < ds.revl_length()) {
        if ((ds)[(i) as usize].name == name) {
            return (ds)[(i) as usize].types.clone();
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return vec![];
}

fn taint_callee_name(tg: Expr) -> String {
    return match tg {
    Expr::Var(vn) => vn,
    Expr::Field(f) => { let f = *f; f.name },
    _ => String::from(""),
};
}

fn taint_call_receiver(c: CallN, ds: &[TaintDecl]) -> bool {
    let cn = taint_callee_name(c.target.clone());
    if (cn == "") {
        return false;
    }
    let ps = taint_params_of(ds, &cn);
    let mut i = 0i64;
    while ((i < c.args.revl_length()) && (i < ps.revl_length())) {
        if (taint_mentions_secret((ps)[(i) as usize].clone()) && taint_expr_mentions((c.args)[(i) as usize].clone(), "result")) {
            return true;
        }
        i = (i).checked_add(1i64).expect("revl: Int overflow");
    }
    return false;
}

fn taint_expr_mentions(e: Expr, bn: &str) -> bool {
    return match e {
    Expr::Var(vn) => (vn == bn),
    Expr::IntLit(_) => false,
    Expr::FloatLit(_) => false,
    Expr::StrLit(_) => false,
    Expr::BoolLit(_) => false,
    Expr::NullLit => false,
    Expr::Hole(_) => false,
    Expr::Asset(_) => false,
    Expr::Bad(_) => false,
    Expr::Bin(b) => { let b = *b; (taint_expr_mentions(b.l.clone(), bn) || taint_expr_mentions(b.r.clone(), bn)) },
    Expr::Un(u) => { let u = *u; taint_expr_mentions(u.e.clone(), bn) },
    Expr::Emit(u) => { let u = *u; taint_expr_mentions(u.e.clone(), bn) },
    Expr::Call(c) => { let c = *c; (taint_expr_mentions(c.target.clone(), bn) || taint_exprs_mention(&c.args, 0i64, bn)) },
    Expr::Field(f) => { let f = *f; taint_expr_mentions(f.target.clone(), bn) },
    Expr::OptField(f) => { let f = *f; taint_expr_mentions(f.target.clone(), bn) },
    Expr::OptCall(c) => { let c = *c; (taint_expr_mentions(c.target.clone(), bn) || taint_exprs_mention(&c.args, 0i64, bn)) },
    Expr::Index(x) => { let x = *x; (taint_expr_mentions(x.target.clone(), bn) || taint_expr_mentions(x.idx.clone(), bn)) },
    Expr::If(x) => { let x = *x; ((taint_expr_mentions(x.cond.clone(), bn) || taint_expr_mentions(x.then_.clone(), bn)) || taint_expr_mentions(x.els.clone(), bn)) },
    Expr::Rec(r) => taint_inits_mention(&r.fields, 0i64, bn),
    Expr::Lst(l) => taint_exprs_mention(&l.items, 0i64, bn),
    Expr::Arrow(a) => { let a = *a; taint_expr_mentions(a.body, bn) },
    Expr::Match(m) => { let m = *m; (taint_expr_mentions(m.scrut.clone(), bn) || taint_arms_mention(&m.arms, 0i64, bn)) },
    Expr::Templ(t) => taint_parts_mention(&t.parts, 0i64, bn),
    Expr::RecUpd(r) => { let r = *r; (taint_expr_mentions(r.base.clone(), bn) || taint_inits_mention(&r.upds, 0i64, bn)) },
    _ => unreachable!(),
};
}

fn taint_exprs_mention(xs: &[Expr], i: i64, bn: &str) -> bool {
    if (i >= xs.revl_length()) {
        return false;
    }
    if taint_expr_mentions((xs)[(i) as usize].clone(), bn) {
        return true;
    }
    return taint_exprs_mention(xs, (i).checked_add(1i64).expect("revl: Int overflow"), bn);
}

