fn duration_ms_str(numText: &str, unit: &str) -> String {
    let mut mult = 0i64;
    if (unit == "ms") {
        mult = 1i64;
    }
    if (unit == "s") {
        mult = 1000i64;
    }
    if (unit == "m") {
        mult = 60000i64;
    }
    if (unit == "h") {
        mult = 3600000i64;
    }
    if (unit == "d") {
        mult = 86400000i64;
    }
    if (mult == 0i64) {
        return String::from("");
    }
    let n = match { let _s = (numText); if _s.starts_with('+') { None } else { _s.parse::<i64>().ok() } } {
    Some(v) => v,
    None => (0i64).checked_sub(1i64).expect("revl: Int overflow"),
    _ => unreachable!(),
};
    if (n < 0i64) {
        return String::from("");
    }
    return (((n).checked_mul(mult).expect("revl: Int overflow"))).to_string();
}

