        if (!ue.ok) {
            return mk_irres(false, String::from(""));
        }
        let step0 = (((String::from("{\"step\": \"effect\", \"acquire\": ").revl_concat(&ae.js)).revl_concat(", \"undo\": ")).revl_concat(&ue.js)).revl_concat("}");
        let step = if isAsync { step_async(&step0) } else { step0.clone() };
