#[test]
fn lexes_a_component_header() {
    let toks = lex_src(String::from("component C requires kv: Kv {}"));
    assert!(((toks)[(0i64) as usize].kind == "kw"));
    assert!(((toks)[(0i64) as usize].text == "component"));
    assert!(((toks)[(1i64) as usize].kind == "ident"));
    assert!(((toks)[(4i64) as usize].kind == ":"));
    assert!((toks.revl_length() == 9i64));
}

#[test]
fn operators_lex_longest_first() {
    let toks = lex_src(String::from("a === b -> c"));
    assert!(((toks)[(1i64) as usize].kind == "==="));
    assert!(((toks)[(3i64) as usize].kind == "arrow"));
}

#[test]
fn template_parts_serialize() {
    let toks = lex_src(String::from("`hi ${name}!`"));
    assert!(((toks)[(0i64) as usize].kind == "template"));
    assert!(((toks)[(0i64) as usize].text == "t:hi |v:name|t:!"));
}

#[test]
fn a_____escape_does_not_close_the_string__item_183_() {
    let toks = lex_src(String::from("let a = \"x\\\"y\""));
    assert!(((toks)[(3i64) as usize].kind == "string"));
    assert!(((toks)[(3i64) as usize].text == "x\"y"));
    assert!(((toks)[(4i64) as usize].kind == "eof"));
}

#[test]
fn a______escape_yields_one_backslash__and_no_other_escape_is_processed() {
    let toks = lex_src(String::from("let a = \"a\\\\b\""));
    assert!(((toks)[(3i64) as usize].text == "a\\b"));
    let raw = lex_src(String::from("let a = \"tab\\there\""));
    assert!(((raw)[(3i64) as usize].text == "tab\\there"));
}

#[test]
fn a_host_body_s_braces_are_balanced_past_a_______string() {
    let toks = lex_src(String::from("@ts { if (c === \"{\") return 1; }"));
    assert!(((toks)[(0i64) as usize].kind == "hostbody"));
    assert!(((toks)[(1i64) as usize].kind == "eof"));
}

#[test]
fn an_interpolation_s_braces_are_balanced_past_a_string_and_a_comment() {
    let toks = lex_src(String::from("let s = `v=${m.get(\"}\")}`"));
    assert!(((toks)[(3i64) as usize].kind == "template"));
    assert!(((toks)[(4i64) as usize].kind == "eof"));
}

#[test]
fn precedence____binds_tighter_than__() {
    assert!((parse_render(String::from("1 + 2 * 3")) == "(bin + (int 1) (bin * (int 2) (int 3)))"));
}

#[test]
fn left_associativity_of__() {
    assert!((parse_render(String::from("a - b - c")) == "(bin - (bin - (var a) (var b)) (var c))"));
}

#[test]
fn ___is_right_associative() {
    assert!((parse_render(String::from("a ?? b ?? c")) == "(bin ?? (var a) (bin ?? (var b) (var c)))"));
}

#[test]
fn ____canonicalizes_to___() {
    assert!((parse_render(String::from("a === b")) == "(bin == (var a) (var b))"));
}

#[test]
fn ___may_not_mix_with____unparenthesised() {
    assert!((parse_render(String::from("a ?? b || c")) == "(bad)"));
}

#[test]
fn parenthesised____may_sit_beside___() {
    assert!((parse_render(String::from("(a ?? b) || c")) == "(bin || (bin ?? (var a) (var b)) (var c))"));
}

#[test]
fn optional_chain_rejects_a_plain_access_after___() {
    assert!((parse_render(String::from("a?.b.c")) == "(bad)"));
}

#[test]
fn ternary_is_right_associative() {
    assert!((parse_render(String::from("a ? b : c ? d : e")) == "(if (var a) (var b) (if (var c) (var d) (var e)))"));
}

#[test]
fn postfix_chains() {
    assert!((parse_render(String::from("f(1).g[2]")) == "(index (field (call (var f) (int 1)) g) (int 2))"));
}

#[test]
fn arrow_with_annotated_params() {
    assert!((parse_render(String::from("(a: Int, b) => a + b")) == "(arrow (p a Int) (p b _) (bin + (var a) (var b)))"));
}

#[test]
fn template_re_parses_its_interpolations() {
    assert!((parse_render(String::from("`n=${r.count}!`")) == "(templ (t n=) (e (field (var r) count)) (t !))"));
}

#[test]
fn match_arms() {
    assert!((parse_render(String::from("match e { Ok(v) => v, _ => 0, }")) == "(match (var e) (arm Ok v (var v)) (arm _ _ (int 0)))"));
}

trait RevlStrOps {
    fn revl_length(&self) -> i64;
    fn revl_slice(&self, a: i64, b: i64) -> String;
    fn revl_index_of(&self, needle: &str) -> i64;
    fn revl_concat(&self, other: &str) -> String;
    fn revl_split(&self, sep: &str) -> Vec<String>;
    fn revl_repeat(&self, n: i64) -> String;
    fn revl_starts_with(&self, prefix: &str) -> bool;
    fn revl_ends_with(&self, suffix: &str) -> bool;
}
impl RevlStrOps for str {
    fn revl_length(&self) -> i64 { self.chars().count() as i64 }
    fn revl_slice(&self, a: i64, b: i64) -> String {
        // JS/Python slice: a negative bound counts from the end, then
        // both bounds clamp into range (docs/stdlib-2.0.md §slice).
        let n = self.chars().count() as i64;
        let a2 = { let x = if a < 0 { a + n } else { a }; x.max(0).min(n) };
        let b2 = { let x = if b < 0 { b + n } else { b }; x.max(0).min(n).max(a2) };
        self.chars().skip(a2 as usize).take((b2 - a2) as usize).collect()
    }
    fn revl_index_of(&self, needle: &str) -> i64 {
        match self.find(needle) {
            Some(b) => self[..b].chars().count() as i64,
            None => -1,
        }
    }
    fn revl_concat(&self, other: &str) -> String { format!("{}{}", self, other) }
    fn revl_split(&self, sep: &str) -> Vec<String> {
        if sep.is_empty() {
            self.chars().map(|c| c.to_string()).collect()
        } else {
            self.split(sep).map(|s| s.to_string()).collect()
        }
    }
    fn revl_repeat(&self, n: i64) -> String { self.repeat(n.max(0) as usize) }
    fn revl_starts_with(&self, prefix: &str) -> bool { self.starts_with(prefix) }
    fn revl_ends_with(&self, suffix: &str) -> bool { self.ends_with(suffix) }
}
trait RevlStrListOps {
    fn revl_join(&self, sep: &str) -> String;
}
impl RevlStrListOps for Vec<String> {
    fn revl_join(&self, sep: &str) -> String { self.join(sep) }
}
impl RevlStrListOps for [String] {
    fn revl_join(&self, sep: &str) -> String { self.join(sep) }
}
trait RevlListOps<T> {
    fn revl_length(&self) -> i64;
    fn revl_slice(&self, a: i64, b: i64) -> Vec<T>;
    fn revl_concat(&self, other: &Vec<T>) -> Vec<T>;
    fn revl_push(&self, item: T) -> Vec<T>;
}
trait RevlListSearchOps<T> {
    fn revl_index_of(&self, needle: &T) -> i64;
}
impl<T: Clone> RevlListOps<T> for Vec<T> {
    fn revl_length(&self) -> i64 { self.len() as i64 }
    fn revl_slice(&self, a: i64, b: i64) -> Vec<T> {
        // JS/Python slice: a negative bound counts from the end, then
        // both bounds clamp into range, never panic (docs §slice).
        let len = self.len() as i64;
        let a2 = { let x = if a < 0 { a + len } else { a }; x.max(0).min(len) as usize };
        let b2 = { let x = if b < 0 { b + len } else { b }; (x.max(0).min(len) as usize).max(a2) };
        self[a2..b2].to_vec()
    }
    fn revl_concat(&self, other: &Vec<T>) -> Vec<T> {
        let mut _v = self.clone(); _v.extend(other.iter().cloned()); _v
    }
    fn revl_push(&self, item: T) -> Vec<T> {
        let mut _v = self.clone(); _v.push(item); _v
    }
}
impl<T: Clone + PartialEq> RevlListSearchOps<T> for Vec<T> {
    fn revl_index_of(&self, needle: &T) -> i64 {
        self.iter().position(|x| x == needle).map(|i| i as i64).unwrap_or(-1)
    }
}
impl<T: Clone> RevlListOps<T> for [T] {
    fn revl_length(&self) -> i64 { self.len() as i64 }
    fn revl_slice(&self, a: i64, b: i64) -> Vec<T> {
        // JS/Python slice: negative bounds count from the end (docs §slice).
        let len = self.len() as i64;
        let a2 = { let x = if a < 0 { a + len } else { a }; x.max(0).min(len) as usize };
        let b2 = { let x = if b < 0 { b + len } else { b }; (x.max(0).min(len) as usize).max(a2) };
        self[a2..b2].to_vec()
    }
    fn revl_concat(&self, other: &Vec<T>) -> Vec<T> { let mut out = self.to_vec(); out.extend(other.iter().cloned()); out }
    fn revl_push(&self, item: T) -> Vec<T> { let mut out = self.to_vec(); out.push(item); out }
}
impl<T: Clone + PartialEq> RevlListSearchOps<T> for [T] {
    fn revl_index_of(&self, needle: &T) -> i64 { self.iter().position(|x| x == needle).map_or(-1, |i| i as i64) }
}
